import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.BW2T23B9.js";const S=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"developer/glossary.md","filePath":"developer/glossary.md","lastUpdated":null}'),i={name:"developer/glossary.md"};function l(o,t,n,s,c,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>术语</th><th>定义</th></tr></thead><tbody><tr><td>Again</td><td>本次未成功提取；进入失败或重学路径</td></tr><tr><td>AI Hub</td><td>AI 功能的集中入口，不是独立聊天后端</td></tr><tr><td>Canonical shape</td><td>新课程内容应写入的标准 JSON 结构</td></tr><tr><td>Course scope</td><td>标识当前课程或导入来源的数据作用域</td></tr><tr><td>D / Difficulty</td><td>FSRS 估计的项目难度</td></tr><tr><td>Derived cache</td><td>可由真理源重新生成的数据</td></tr><tr><td>due</td><td>项目下一次可进入正式复习的时间</td></tr><tr><td>Fidelity rendering</td><td>保留原 Anki HTML/CSS/必要模板行为的渲染路径</td></tr><tr><td>FSRS</td><td>Free Spaced Repetition Scheduler</td></tr><tr><td>Full mode</td><td>为较小 Anki 牌组生成完整课程树投影</td></tr><tr><td>Interaction</td><td>Lesson 中最小可执行题目或展示单元</td></tr><tr><td>Lesson</td><td>Unit 下的单次学习单元</td></tr><tr><td>Lite mode</td><td>大牌组的轻量课程投影模式</td></tr><tr><td>Local-first</td><td>核心状态默认在本地，网络是可选能力</td></tr><tr><td>Notetype</td><td>Anki note 的字段和卡片模板定义</td></tr><tr><td>Official owner</td><td>由 Official Anki Collection 和 scheduler 持有状态的来源</td></tr><tr><td>Pre-render cache</td><td>执行一次模板脚本后保存的无脚本纯 HTML</td></tr><tr><td>R / Retrievability</td><td>当前时刻成功提取的估计概率</td></tr><tr><td>reseed</td><td>根据课程内容版本重建数据库课程投影</td></tr><tr><td>Review event</td><td>一次评分及其前后调度状态记录</td></tr><tr><td>runtimeType</td><td>Interaction JSON 的变体标识</td></tr><tr><td>S / Stability</td><td>FSRS 估计的记忆保持时间尺度</td></tr><tr><td>Safe mode</td><td>临时关闭实验、脚本和外部卡片网络的运行时覆盖</td></tr><tr><td>Section</td><td>课程最高内容层级，通常对应 CEFR 范围</td></tr><tr><td>Sibling cards</td><td>同一 Anki note 生成的多张 card</td></tr><tr><td>Source of truth</td><td>对某类数据具有最终所有权的存储</td></tr><tr><td>Stage</td><td>按顺序包含多个 Interaction 的执行阶段</td></tr><tr><td>Structured rendering</td><td>将卡片或课程内容映射为原生结构化控件</td></tr><tr><td>Unit</td><td>Section 下的主题分组</td></tr><tr><td>Weak item</td><td>由多次学习证据推导出的高风险项目</td></tr></tbody></table><h2 id="术语边界" tabindex="-1">术语边界 <a class="header-anchor" href="#术语边界" aria-label="Permalink to &quot;术语边界&quot;">​</a></h2><ul><li>“课程缓存”不等于“学习状态”。</li><li>“AI 缓存”不等于“AI 会话”。</li><li>“导入成功”不等于“所有媒体完整”。</li><li>“卡片可显示”不等于“卡片允许联网”。</li><li>“Lesson 完成”不等于“项目已长期掌握”。</li><li>“错误一次”不等于“弱项”。</li><li>“目标保持率”不等于测验正确率。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/developer/architecture">架构总览</a></li><li><a href="/docs/guide/memory-state">记忆状态与评分</a></li><li><a href="/docs/guide/faq">常见问题</a></li></ul>',6)])])}const f=d(i,[["render",l]]);export{S as __pageData,f as default};
